    const kgrid = Float64Array.from({length: N}, (_, i) =&gt; 2 * Math.PI * (i &lt; N / 2 ? i : i - N) / L);
    return {key, x, re, im, t: 0, absT: 0, done: false,
      kr: kgrid.map(k =&gt; Math.cos(-k * k * dt / (2 * m))), ki: kgrid.map(k =&gt; Math.sin(-k * k * dt / (2 * m))),
