  const fft = (ar, ai, sign) =&gt; {
    for (let i = 1, j = 0; i &lt; N; i++) { let bit = N &gt;&gt; 1; for (; j & bit; bit &gt;&gt;= 1) j ^= bit; j ^= bit; if (i &lt; j) { [ar[i], ar[j]] = [ar[j], ar[i]]; [ai[i], ai[j]] = [ai[j], ai[i]]; } }
    for (let len = 2; len &lt;= N; len &lt;&lt;= 1) {
      const ang = sign * 2 * Math.PI / len, wr = Math.cos(ang), wi = Math.sin(ang);
