  const frame = (S) =&gt; {
    const P = []; let PT = 0;
    for (let i = 0; i &lt; N; i += 2) P.push({x: S.x[i], P: S.re[i] ** 2 + S.im[i] ** 2});
    for (let i = 0; i &lt; N; i++) if (S.x[i] &gt; lt) PT += (S.re[i] ** 2 + S.im[i] ** 2) * dx;
    return {P, t: S.t, T: PT + S.absT, V0: V0t, l: lt, done: S.done};
  };
  if (!ctl.sim || ctl.sim.key !== key) ctl.sim = init();        // new parameters: start from the beginning
  if (ctl.dataset.running === "1" && ctl.sim.done) ctl.sim = init();   // Play after the end: run again
  let S = ctl.sim;
  yield frame(S);
  while (ctl.dataset.running === "1" && S.t &lt; S.tmax) {
    for (let s = 0; s &lt; 12; s++) {
